	if gf, gh := footerDots(f); gf+gh != 0 {
		t.Errorf("an error footer still carries a dot: %q", f)
	}
	if !strings.Contains(f, "api") && !strings.Contains(strings.ToLower(f), "fail") {
		t.Errorf("the error text is not in the footer: %q", f)
	}
}
